//-----------------------------------------------------------------------------
// convert to usdrt
//-----------------------------------------------------------------------------

template <typename R, typename P>
inline const R& toUsdrt(const P& pxrObj)
{
    return reinterpret_cast<const R&>(pxrObj);
}

// GfHalf
inline GfHalf toUsdrt(PXR_NS::GfHalf v)
{
    return toUsdrt<GfHalf, PXR_NS::GfHalf>(v);
}

// Vec2
inline GfVec2d toUsdrt(PXR_NS::GfVec2d v)
{
    return toUsdrt<GfVec2d, PXR_NS::GfVec2d>(v);
}
