// Matrix
inline GfMatrix2d toUsdrt(PXR_NS::GfMatrix2d v)
{
    return toUsdrt<GfMatrix2d, PXR_NS::GfMatrix2d>(v);
}
inline GfMatrix2f toUsdrt(PXR_NS::GfMatrix2f v)
{
    return toUsdrt<GfMatrix2f, PXR_NS::GfMatrix2f>(v);
}
inline GfMatrix3d toUsdrt(PXR_NS::GfMatrix3d v)
{
    return toUsdrt<GfMatrix3d, PXR_NS::GfMatrix3d>(v);
}
